/**
 * Typed access to the committed budget data in src/data/budget/ (generated by
 * tools/ingest-budget.ts, format in docs/budget-data.md). Validated with the
 * shared schema when the module loads. Amounts are mn kr, nominal.
 */
import metaJson from '@/data/budget/meta.json';
import expenditureJson from '@/data/budget/expenditure.json';
import revenueJson from '@/data/budget/revenue.json';
import {
  budgetMetaSchema,
  expenditureSchema,
  revenueSchema,
  type Anslag,
  type BudgetStatus,
  type OvrigtKey,
  type Series,
} from '@/schema/budget';

export const meta = budgetMetaSchema.parse(metaJson);
const expenditure = expenditureSchema.parse(expenditureJson);
const revenue = revenueSchema.parse(revenueJson);

/** Series in all three files are indexed by meta.years, so the year lists must be identical. */
export function assertSameYears(metaYears: number[], expYears: number[], revYears: number[]): void {
  if (expYears.join() !== metaYears.join())
    throw new Error('expenditure.json years differ from meta.json');
  if (revYears.join() !== metaYears.join())
    throw new Error('revenue.json years differ from meta.json');
}
assertSameYears(meta.years, expenditure.years, revenue.years);

export type RevenueTitel = (typeof revenue.titlar)[number];

export const years: readonly number[] = meta.years;
export const latestYear: number = years[years.length - 1];

function indexOfYear(year: number): number {
  const i = years.indexOf(year);
  if (i === -1) throw new Error(`No budget data for ${year}`);
  return i;
}

/** Empty source cells count as 0 in sums; display code decides how to show null. */
const n = (v: number | null | undefined): number => v ?? 0;

/** Round away floating point noise from sums of one-decimal values. */
const round1 = (v: number): number => Math.round(v * 10) / 10;

function sumAt(series: Series[], i: number): number {
  return round1(series.reduce((sum, s) => sum + n(s[i]), 0));
}

// --- Expenditure -------------------------------------------------------------

/** The 27 utgiftsområden, restated names. */
export const areas = expenditure.uo;

export function areaByNr(nr: number) {
  return expenditure.uo.find((u) => u.nr === nr);
}

const anslagByKodMap = new Map(expenditure.anslag.map((a) => [a.kod, a]));

/** Look up an anslag by its restated code, including the suffix of discontinued ones ("0501003 2024"). */
export function anslagByKod(kod: string): Anslag | undefined {
  return anslagByKodMap.get(kod);
}

/** All anslag of a UO, active and discontinued, sorted by code. */
export function anslagForUo(uo: number): Anslag[] {
  return expenditure.anslag.filter((a) => a.uo === uo);
}

/**
 * Anslag that are not discontinued (no year suffix in the code): the ones that get their own page.
 * The 2025 file has 503 anslag rows, but 13 of them are suffixed (discontinued) codes with no budget and
 * (bar one, 0301004 2024) no outcome, so 490 are active.
 */
export function activeAnslag(): Anslag[] {
  return expenditure.anslag.filter((a) => a.upphort === null);
}

/** Outcome of one UO in one year (sum over its anslag). */
export function uoUtfall(uo: number, year: number): number {
  return sumAt(
    anslagForUo(uo).map((a) => a.utfall),
    indexOfYear(year),
  );
}

/** Rows without a utgiftsområde (nettoutlåning, kassamässig korrigering, ...), outcome per year. */
export function ovrigt(key: OvrigtKey): Series {
  return expenditure.ovrigt[key];
}

/** Sum of the outcome of UO 1-27. */
export function uoSumUtfall(year: number): number {
  return sumAt(
    expenditure.anslag.map((a) => a.utfall),
    indexOfYear(year),
  );
}

/** Statens utgifter = UO 1-27 + Riksgäldskontorets nettoutlåning + kassamässig korrigering. */
export function statensUtgifter(year: number): number {
  const i = indexOfYear(year);
  return round1(
    uoSumUtfall(year) +
      n(expenditure.ovrigt.nettoutlaning[i]) +
      n(expenditure.ovrigt.kassamassigKorrigering[i]),
  );
}

// --- Revenue -----------------------------------------------------------------

export const revenueTyper = revenue.typ;
export const revenueHuvudgrupper = revenue.huvudgrupp;
export const revenueTitelgrupper = revenue.titelgrupp;
export const revenueTitlar = revenue.titlar;

export type RevenueNode = {
  kod: string;
  namn: string;
  /** Outcome per year aligned on `years`; sum of the node's titlar, empty cells as 0. */
  utfall: number[];
  children: RevenueNode[];
};

function sumSeries(titlar: RevenueTitel[]): number[] {
  return years.map((_, i) =>
    sumAt(
      titlar.map((t) => t.utfall),
      i,
    ),
  );
}

function leaf(t: RevenueTitel): RevenueNode {
  return { kod: t.kod, namn: t.namn, utfall: years.map((_, i) => n(t.utfall[i])), children: [] };
}

/**
 * Revenue tree typ -> huvudgrupp -> titelgrupp -> titel. Titles without a
 * titelgrupp appear directly under their huvudgrupp. Leaves have no children.
 */
export function revenueTree(): RevenueNode[] {
  return revenue.typ.map((typ) => {
    const huvudgrupper = revenue.huvudgrupp.filter((h) => h.typ === typ.kod);
    const nodes = huvudgrupper.map((h): RevenueNode => {
      const own = revenue.titlar.filter((t) => t.huvudgrupp === h.kod);
      const groups = revenue.titelgrupp
        .filter((g) => g.huvudgrupp === h.kod)
        .map((g): RevenueNode => {
          const titlar = own.filter((t) => t.titelgrupp === g.kod);
          return {
            kod: g.kod,
            namn: g.namn,
            utfall: sumSeries(titlar),
            children: titlar.map(leaf),
          };
        });
      const loose = own.filter((t) => t.titelgrupp === null).map(leaf);
      return { kod: h.kod, namn: h.namn, utfall: sumSeries(own), children: [...groups, ...loose] };
    });
    const utfall = years.map((_, i) => round1(nodes.reduce((s, h) => s + h.utfall[i], 0)));
    return { kod: typ.kod, namn: typ.namn, utfall, children: nodes };
  });
}

/** Statens inkomster = sum of the outcome of all inkomsttitlar, signs as in the file. */
export function statensInkomster(year: number): number {
  return sumAt(
    revenue.titlar.map((t) => t.utfall),
    indexOfYear(year),
  );
}

// --- Totals ------------------------------------------------------------------

export type YearTotals = {
  year: number;
  /** Statens utgifter (UO 1-27 + nettoutlåning + kassamässig korrigering). */
  utgifter: number;
  /** Sum of UO 1-27 only. */
  uoSum: number;
  inkomster: number;
  /** Inkomster minus utgifter; negative is a deficit. */
  saldo: number;
  expenditureStatus: BudgetStatus;
  revenueStatus: BudgetStatus;
};

export function totalsForYear(year: number): YearTotals {
  const utgifter = statensUtgifter(year);
  const inkomster = statensInkomster(year);
  return {
    year,
    utgifter,
    uoSum: uoSumUtfall(year),
    inkomster,
    saldo: round1(inkomster - utgifter),
    expenditureStatus: meta.yearStatus.expenditure[String(year)],
    revenueStatus: meta.yearStatus.revenue[String(year)],
  };
}

export function totalsPerYear(): YearTotals[] {
  return years.map(totalsForYear);
}
